package com.shikshasetu.controller;

import com.shikshasetu.model.*;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import com.shikshasetu.service.PortalAuditService;import com.shikshasetu.service.ChatEngagementAnalyticsService;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
import java.time.*;import java.util.*;import java.util.stream.Collectors;

@RestController @RequestMapping("/api/institution-admin") public class InstitutionAdminController{
 private final InstitutionRepository institutions;private final PortalUserRepository users;private final StudentRepository students;private final ChatInteractionRepository chats;private final StudentProgressRepository progress;private final PortalAuditLogRepository auditLogs;private final PortalAuditService audit;private final PortalSessionRepository sessions;private final ChatEngagementAnalyticsService engagementAnalytics;
 @Value("${shikshasetu.privacy.chat-retention-days:90}") private int chatRetentionDays;
 public InstitutionAdminController(InstitutionRepository i,PortalUserRepository u,StudentRepository s,ChatInteractionRepository c,StudentProgressRepository p,PortalAuditLogRepository a,PortalAuditService audit,PortalSessionRepository sessions,ChatEngagementAnalyticsService engagementAnalytics){institutions=i;users=u;students=s;chats=c;progress=p;auditLogs=a;this.audit=audit;this.sessions=sessions;this.engagementAnalytics=engagementAnalytics;}
 public record DecisionRequest(@NotBlank @Pattern(regexp="APPROVE|REJECT") String decision,String note){}
 public record AccountStatusRequest(@NotBlank @Pattern(regexp="ACTIVE|SUSPENDED") String status){}
 @GetMapping("/overview") public Map<String,Object> overview(){PortalPrincipal p=PortalAuthContext.require();Long tenant=p.institutionId();if(tenant==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"An institution context is required");List<Student> all=students.findAllByInstitutionId(tenant);List<ChatInteraction> interactions=chats.findByInstitutionIdAndCreatedAtAfterAndExpiresAtAfter(tenant,LocalDateTime.now().minusDays(30),LocalDateTime.now());return Map.of("institution",institutionMap(requireInstitution(tenant)),"students",all.size(),"pendingRequests",users.countByInstitutionIdAndAccountStatus(tenant,"PENDING"),"admins",users.findByInstitutionIdOrderByCreatedAtDesc(tenant).stream().filter(x->"INSTITUTION_ADMIN".equals(x.getRole())).count(),"chatInteractionsLast30Days",interactions.size(),"uniqueChatUsersLast30Days",interactions.stream().filter(x->x.getStudentId()!=null).map(ChatInteraction::getStudentId).distinct().count(),"chatRetentionDays",chatRetentionDays);}
 @GetMapping("/enrollment-requests") public List<Map<String,Object>> requests(){Long tenant=PortalAuthContext.require().institutionId();return users.findByInstitutionIdAndAccountStatusOrderByCreatedAtAsc(tenant,"PENDING").stream().map(this::userView).toList();}
 @PostMapping("/enrollment-requests/{userId}/decision") @Transactional public Map<String,Object> decide(@PathVariable Long userId,@Valid @RequestBody DecisionRequest r){Long tenant=PortalAuthContext.require().institutionId();PortalUser u=users.findById(userId).filter(x->Objects.equals(x.getInstitutionId(),tenant)&&"PENDING".equals(x.getAccountStatus())&&"STUDENT".equals(x.getRole())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pending enrollment request not found"));if("APPROVE".equals(r.decision())){Student s=new Student();s.setInstitutionId(tenant);s.setStudentCode("STU-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT));s.setFullName(u.getFullName());s.setEmail(u.getEmail());s.setAttendance(0);s.setInternalMarks(0);s.setAssignmentsCompleted(0);s.setPreviousFailures(0);s.setAbsences(0);students.save(s);u.setStudentId(s.getId());u.setAccountStatus("ACTIVE");}else{u.setAccountStatus("REJECTED");}users.save(u);audit.record("ENROLLMENT_"+r.decision(),u.getId(),r.note()==null?"":r.note().trim());return Map.of("userId",u.getId(),"status",u.getAccountStatus(),"studentId",u.getStudentId()==null?0:u.getStudentId());}
 @GetMapping("/students") public List<Map<String,Object>> studentAccounts(){Long tenant=PortalAuthContext.require().institutionId();return users.findByInstitutionIdOrderByCreatedAtDesc(tenant).stream().filter(u->"STUDENT".equals(u.getRole())).map(this::userView).toList();}
 @PatchMapping("/students/{userId}/status") @Transactional public Map<String,Object> studentAccountStatus(@PathVariable Long userId,@Valid @RequestBody AccountStatusRequest request){Long tenant=PortalAuthContext.require().institutionId();PortalUser student=users.findById(userId).filter(x->Objects.equals(x.getInstitutionId(),tenant)&&"STUDENT".equals(x.getRole())&&x.getStudentId()!=null).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student account not found"));student.setAccountStatus(request.status());users.save(student);if("SUSPENDED".equals(request.status())){List<PortalSession> active=sessions.findByUserIdAndRevokedAtIsNull(userId);active.forEach(PortalSession::revoke);sessions.saveAll(active);}audit.record("STUDENT_ACCOUNT_STATUS_CHANGED",userId,"Student account status="+request.status()+("SUSPENDED".equals(request.status())?"; active sessions revoked":""));return Map.of("userId",userId,"status",student.getAccountStatus());}
 @GetMapping("/chat-analytics") public Map<String,Object> chatAnalytics(@RequestParam(defaultValue="30") int days){Long tenant=PortalAuthContext.require().institutionId();int safeDays=Math.max(1,Math.min(days,180));List<ChatInteraction> rows=chats.findByInstitutionIdAndCreatedAtAfterAndExpiresAtAfter(tenant,LocalDateTime.now().minusDays(safeDays),LocalDateTime.now());Map<String,Long> topics=rows.stream().collect(Collectors.groupingBy(ChatInteraction::getTopic,TreeMap::new,Collectors.counting()));Map<String,Long> sentiments=rows.stream().collect(Collectors.groupingBy(ChatInteraction::getSentiment,TreeMap::new,Collectors.counting()));Map<String,Long> daily=rows.stream().collect(Collectors.groupingBy(x->x.getCreatedAt().toLocalDate().toString(),TreeMap::new,Collectors.counting()));List<Map<String,Object>> engagement=engagementAnalytics.analyseInstitution(tenant,safeDays).stream().map(x->{Student st=students.findByInstitutionIdAndId(tenant,x.studentId()).orElse(null);Map<String,Object> m=new LinkedHashMap<>();m.put("studentId",x.studentId());m.put("studentName",st==null?"Student":st.getFullName());m.put("studentCode",st==null?"":st.getStudentCode());m.put("interactions",x.interactions());m.put("activeDays",x.activeDays());m.put("distinctTopics",x.distinctTopics());m.put("averageMessageLength",x.averageMessageLength());m.put("activityBand",x.activityBand());return m;}).toList();return Map.of("periodDays",safeDays,"totalInteractions",rows.size(),"uniqueStudents",rows.stream().filter(x->x.getStudentId()!=null).map(ChatInteraction::getStudentId).distinct().count(),"topics",topics,"sentiments",sentiments,"dailyInteractions",daily,"studentEngagement",engagement,"engagementModel","Weka SimpleKMeans · unsupervised activity grouping from interaction counts, active days, topic breadth and average message length","notice","Topics and emotional-tone cues are transparent keyword estimates, not diagnoses. Activity bands are descriptive usage groups, not measures of ability, wellbeing or risk. The existing Weka Random Forest is the separate academic deterioration model.");}
 @GetMapping("/chat-interactions") public List<Map<String,Object>> chatRecords(@RequestParam(required=false) Long studentId,@RequestParam String reason){if(reason==null||reason.trim().length()<10||reason.trim().length()>300)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide a review reason between 10 and 300 characters");Long tenant=PortalAuthContext.require().institutionId();List<ChatInteraction> rows=studentId==null?chats.findTop500ByInstitutionIdAndExpiresAtAfterOrderByCreatedAtDesc(tenant,LocalDateTime.now()):chats.findTop500ByStudentIdAndExpiresAtAfterOrderByCreatedAtDesc(studentId,LocalDateTime.now()).stream().filter(x->Objects.equals(x.getInstitutionId(),tenant)).toList();audit.record("CHAT_CONVERSATIONS_REVIEWED",studentId,"Administrator opened " + rows.size() + " retained conversation records. Reason: " + reason.trim());return rows.stream().map(x->{PortalUser u=users.findById(x.getUserId()).orElse(null);Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("studentId",x.getStudentId());m.put("studentName",u==null?"Former account":u.getFullName());m.put("email",u==null?"":u.getEmail());m.put("topic",x.getTopic());m.put("sentiment",x.getSentiment());m.put("message",x.getUserMessage());m.put("reply",x.getAssistantReply());m.put("createdAt",x.getCreatedAt());m.put("expiresAt",x.getExpiresAt());return m;}).toList();}
 @PostMapping("/progress/{studentId}") @Transactional public StudentProgress addProgress(@PathVariable Long studentId,@Valid @RequestBody StudentSelfController.ProgressRequest r){Long tenant=PortalAuthContext.require().institutionId();Student s=students.findByInstitutionIdAndId(tenant,studentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found"));if(r.assignmentsDone()>r.assignmentsTotal())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Completed assignments cannot exceed total assignments");StudentProgress item=new StudentProgress(tenant,s.getId(),PortalAuthContext.require().userId(),r.attendance(),r.assignmentsDone(),r.assignmentsTotal(),r.problems(),r.hours(),r.note()==null?"":r.note().trim());audit.record("ADMIN_PROGRESS_SAVED",s.getId(),"Administrator recorded a progress check-in");return progress.save(item);}
 @GetMapping("/progress") public List<Map<String,Object>> progressRecords(){Long tenant=PortalAuthContext.require().institutionId();return progress.findTop500ByInstitutionIdOrderByCreatedAtDesc(tenant).stream().map(x->{Student s=students.findByInstitutionIdAndId(tenant,x.getStudentId()).orElse(null);Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("studentId",x.getStudentId());m.put("studentName",s==null?"Former student":s.getFullName());m.put("attendance",x.getAttendance());m.put("assignmentsDone",x.getAssignmentsDone());m.put("assignmentsTotal",x.getAssignmentsTotal());m.put("problems",x.getProblems());m.put("hours",x.getHours());m.put("note",x.getNote());m.put("createdAt",x.getCreatedAt());return m;}).toList();}
 @GetMapping("/audit-logs") public List<PortalAuditLog> logs(){return auditLogs.findTop250ByInstitutionIdOrderByCreatedAtDesc(PortalAuthContext.require().institutionId());}
 @GetMapping("/settings") public Map<String,Object> settings(){return institutionMap(requireInstitution(PortalAuthContext.require().institutionId()));}
 @PutMapping("/settings") @Transactional public Map<String,Object> updateSettings(@RequestBody Map<String,Object> body){Institution i=requireInstitution(PortalAuthContext.require().institutionId());Object name=body.get("name");if(name instanceof String s&&!s.isBlank()&&s.length()<=160)i.setName(s.trim());Object enrollmentOpen=body.get("enrollmentOpen");if(enrollmentOpen instanceof Boolean open)i.setEnrollmentOpen(open);Object settings=body.get("settings");if(settings instanceof Map<?,?> m){try{i.setSettingsJson(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(m));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Settings must be valid JSON");}}institutions.save(i);audit.record("INSTITUTION_SETTINGS_UPDATED",i.getId(),"Institution settings updated");return institutionMap(i);}
 @PostMapping("/access-code/rotate") @Transactional public Map<String,Object> rotateAccessCode(){Institution i=requireInstitution(PortalAuthContext.require().institutionId());String code;do{code=generateAccessCode();}while(institutions.findByAccessCodeIgnoreCase(code).isPresent());i.setAccessCode(code);institutions.save(i);audit.record("INSTITUTION_ACCESS_CODE_ROTATED",i.getId(),"Institution enrollment access code rotated");return Map.of("accessCode",code,"message","The previous code can no longer be used for new enrollment requests.");}
 private String generateAccessCode(){byte[] bytes=new byte[6];new java.security.SecureRandom().nextBytes(bytes);return "SS-"+Base64.getUrlEncoder().withoutPadding().encodeToString(bytes).replace('-','X').replace('_','Y').toUpperCase(Locale.ROOT).substring(0,8);}
 private Institution requireInstitution(Long id){return institutions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Institution not found"));}
 private Map<String,Object> institutionMap(Institution i){return Map.of("id",i.getId(),"name",i.getName(),"accessCode",i.getAccessCode(),"active",i.isActive(),"enrollmentOpen",i.isEnrollmentOpen(),"settingsJson",i.getSettingsJson()==null?"{}":i.getSettingsJson());}
 private Map<String,Object> userView(PortalUser u){Map<String,Object> m=new LinkedHashMap<>();m.put("userId",u.getId());m.put("fullName",u.getFullName());m.put("email",u.getEmail());m.put("role",u.getRole());m.put("status",u.getAccountStatus());m.put("studentId",u.getStudentId());m.put("requestedAt",u.getCreatedAt());m.put("chatMonitoringConsent",u.isChatMonitoringConsent());return m;}
}
